<?php $title='Potensi Desa'; require 'includes/header.php'; $rows=$pdo->query('SELECT * FROM potentials ORDER BY id DESC')->fetchAll(); ?><section class="page-head"><div class="container"><h1 class="section-title">Potensi Desa</h1><p class="text-muted">Potensi lokal yang dapat dikembangkan dan dipromosikan.</p></div></section><main class="container py-5"><div class="row g-4"><?php foreach($rows as $r):?><div class="col-md-4"><div class="card card-soft overflow-hidden"><?php if($r['gambar']):?><img src="<?=e($r['gambar'])?>" class="thumb w-100"><?php endif;?><div class="card-body"><span class="badge text-bg-light"><?=e($r['kategori'])?></span><h5 class="mt-2"><?=e($r['nama'])?></h5><p><?=e($r['deskripsi'])?></p><small class="text-muted"><?=e($r['lokasi'])?></small></div></div></div><?php endforeach;?></div></main><?php require 'includes/footer.php'; ?>
